<?php
declare(strict_types=1);
namespace App\Http\Controllers\Admin\Plans;
use App\Http\Controllers\Controller;use App\Http\Requests\Admin\Plans\StorePlanRequest;use App\Http\Requests\Admin\Plans\UpdatePlanRequest;use App\Models\Admin\Plans\Plan;use Illuminate\Http\RedirectResponse;use Illuminate\View\View;
final class PlanController extends Controller { public function index():View{$plans=Plan::query()->latest()->paginate(20)->withQueryString();return view('admin.plans.index',['plans'=>$plans,'statistics'=>[['label'=>'إجمالي الباقات','value'=>Plan::count(),'icon'=>'ti-box-seam','tone'=>'primary'],['label'=>'الباقات النشطة','value'=>Plan::where('is_active',true)->count(),'icon'=>'ti-circle-check','tone'=>'success'],['label'=>'الباقات المتاحة','value'=>Plan::publiclyAvailable()->count(),'icon'=>'ti-world-check','tone'=>'info'],['label'=>'الباقات غير المحدودة','value'=>Plan::where('limits_mode','unlimited')->count(),'icon'=>'ti-infinity','tone'=>'warning'],['label'=>'بها خصم','value'=>Plan::where('discount_percentage','>',0)->count(),'icon'=>'ti-discount-2','tone'=>'danger']]]);} public function create():View{return view('admin.plans.create',['plan'=>new Plan]);} public function store(StorePlanRequest $r):RedirectResponse{$plan=Plan::create($r->validated());return to_route('admin.plans.show',$plan)->with('success','تم إنشاء الباقة بنجاح.');} public function show(Plan $plan):View{return view('admin.plans.show',compact('plan'));} public function edit(Plan $plan):View{return view('admin.plans.edit',compact('plan'));} public function update(UpdatePlanRequest $r,Plan $plan):RedirectResponse{$plan->update($r->validated());return to_route('admin.plans.show',$plan)->with('success','تم حفظ التعديلات.');} public function toggleStatus(Plan $plan):RedirectResponse{$plan->update(['is_active'=>!$plan->is_active]);return back()->with('success','تم تحديث حالة الباقة.');}}